/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = path.dirname(fileURLToPath(import.meta.url))
const assets = [
  'data/workshop.json',
  'mechanics/ep-graph/data/ep-graph.v1.json',
  'mechanics/sdk-graph/data/sdk-graph.v1.json',
]

for (const rel of assets) {
  const from = path.resolve(dir, '../src', rel)
  const to = path.resolve(dir, '../dist', rel)
  if (!fs.existsSync(from)) throw new Error(`[sdk] missing asset ${from}`)
  fs.mkdirSync(path.dirname(to), { recursive: true })
  fs.copyFileSync(from, to)
  console.log(`[sdk] copied asset ${rel}`)
}
